import { SQSClient, CreateQueueCommand, GetQueueUrlCommand } from '@aws-sdk/client-sqs';

const client = new SQSClient({ region: 'us-east-1' });

async function createQueueWithDLQ() {
  // Create the DLQ first
  const dlqResult = await client.send(new CreateQueueCommand({ QueueName: 'orders-dlq' }));
  const dlqUrl = dlqResult.QueueUrl!;

  // Get the DLQ ARN
  const dlqAttr = await client.send(new GetQueueUrlCommand({ QueueName: 'orders-dlq' }));
  const dlqArn = (await client.send(new GetQueueAttributesCommand({
    QueueUrl: dlqUrl,
    AttributeNames: ['QueueArn']
  }))).Attributes!.QueueArn!;

  // Create the main queue with redrive policy
  await client.send(new CreateQueueCommand({
    QueueName: 'orders',
    RedrivePolicy: JSON.stringify({
      deadLetterTargetArn: dlqArn,
      maxReceiveCount: 5
    })
  }));
}
